'use strict';
const D=window.ELECTION_DATA, $=s=>document.querySelector(s), nf=new Intl.NumberFormat('pt-BR'), pf=new Intl.NumberFormat('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2});
const n=v=>v==null?'—':nf.format(v), p=v=>v==null?'—':pf.format(v)+'%', pct=(a,b)=>b?100*a/b:null, esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const views=['joinville','municipios','bairros','locais','fontes','emendas'];
function routeFromHash(){
  const [rawView,query='']=location.hash.slice(1).split('?'),params=new URLSearchParams(query);
  const view=views.includes(rawView)?rawView:'joinville';
  const city=D.municipalities.some(c=>String(c.code)===params.get('cidade'))?params.get('cidade'):'81795';
  const validYear=(window.AMENDMENTS_DATA?.meta.years||[]).map(String).includes(params.get('ano'));
  return {view,city,emendaCity:view==='emendas'&&params.has('cidade')&&D.municipalities.some(c=>String(c.code)===params.get('cidade'))?city:'',emendaYear:validYear?params.get('ano'):'all'};
}
let state={...routeFromHash(),neighborhood:null,location:null,search:'',sort:'votes',page:0,emendaSort:'amount',emendaSearch:'',emendaAll:false,emendaPage:0};
function syncAmendmentsHash(){
  const params=new URLSearchParams();
  if(state.view==='emendas'){
    if(state.emendaCity)params.set('cidade',state.emendaCity);
    if(state.emendaYear!=='all')params.set('ano',state.emendaYear);
  }else if(['joinville','bairros','locais'].includes(state.view)&&state.city!=='81795')params.set('cidade',state.city);
  history.replaceState(null,'','#'+state.view+(params.size?'?'+params.toString():''));
}
function openAmendments(code=''){
  const city=D.municipalities.find(c=>String(c.code)===String(code));
  state.view='emendas';state.emendaCity=city?String(city.code):'';
  if(city)state.city=String(city.code);
  state.emendaSearch='';state.emendaPage=0;
  syncAmendmentsHash();render();window.scrollTo({top:0,behavior:'auto'});
}
window.addEventListener('hashchange',()=>{if(location.hash==='#main')return;Object.assign(state,routeFromHash(),{neighborhood:null,location:null,page:0,emendaPage:0,search:'',emendaSearch:''});render()});
const currentCity=()=>D.municipalities.find(x=>String(x.code)===state.city)||D.municipalities[0];
const byCity=(rows=D.neighborhoods)=>rows.filter(x=>String(x.municipalityCode)===state.city);
const metric=(label,value,note,featured=false)=>`<article class="metric ${featured?'featured':''}"><div class="label">${label}</div><div class="value">${value}</div><div class="note">${note}</div></article>`;
const panel=(title,desc,body,extra='')=>`<section class="panel"><div class="panel-head"><div><h2>${title}</h2>${desc?`<p>${desc}</p>`:''}</div>${extra}</div>${body}</section>`;
const noResults=()=>`<div class="empty"><strong>Nenhum resultado para esta busca</strong>Tente outro nome, zona ou número de seção.</div>`;
const empty=()=>`<div class="empty"><strong>Detalhamento em verificação</strong>Os votos por bairro só serão apresentados após a conciliação das seções com os locais de votação.</div>`;
function nav(view,opts={}){state={...state,view,neighborhood:null,location:null,search:'',page:0,...opts};if(view==='emendas'){state.emendaCity='';state.emendaSearch='';state.emendaPage=0;}syncAmendmentsHash();render();}
function stats(c){return `<div class="metrics">${metric('Votos em '+esc(c.name),n(c.votes),c.ranking?n(c.ranking)+'º em votos na cidade · 30000':'Matheus Cadorin · 30000',true)}${metric('% dos votos válidos',p(pct(c.votes,c.validVotes)),n(c.validVotes)+' válidos para deputado estadual')}${metric('Peso na votação estadual',p(pct(c.votes,D.state.votes)),n(c.votes)+' de '+n(D.state.votes)+' votos em SC')}${metric('Seções totalizadas',n(c.countedSections)+' / '+n(c.totalSections),p(pct(c.countedSections,c.totalSections))+' da apuração municipal')}</div>`;}
function bars(rows,limit=8){const sorted=[...rows].sort((a,b)=>b.votes-a.votes).slice(0,limit), max=sorted[0]?.votes||1;return `<div class="panel-body"><div class="bar-legend"><span>Votos do candidato</span><span>% dos válidos locais</span></div>${sorted.map(r=>`<div class="bar-row"><button data-neighborhood="${esc(r.name)}" title="Abrir ${esc(r.name)}">${esc(r.name)}</button><div class="bar-track"><div class="bar-fill" style="width:${100*r.votes/max}%"></div></div><strong class="count">${n(r.votes)}</strong><span class="percent">${p(pct(r.votes,r.validVotes))}</span></div>`).join('')}</div>`;}
function share(c){return `<div class="panel-body"><div class="large-share"><strong>${p(pct(c.votes,D.state.votes))}</strong><span>dos votos em SC</span></div><div class="stacked" role="img" aria-label="${esc(c.name)} representa ${p(pct(c.votes,D.state.votes))} dos votos estaduais"><span style="width:${pct(c.votes,D.state.votes)||0}%"></span><span style="flex:1"></span></div><div class="stat-row"><span><i class="swatch"></i>${esc(c.name)}</span><strong>${n(c.votes)}</strong></div><div class="stat-row"><span><i class="swatch gray"></i>Demais municípios</span><strong>${n(D.state.votes-c.votes)}</strong></div><div class="stat-row"><span>Total em Santa Catarina</span><strong>${n(D.state.votes)}</strong></div><p class="small">Participação do município no total de votos de Cadorin no estado.</p></div>`;}
function summary(c){return `<div class="panel-body">${[['Eleitores aptos',c.electorate],['Comparecimento',c.turnout],['Abstenções',c.electorate-c.turnout],['Votos nominais válidos',c.nominalVotes],['Votos de legenda',c.legendVotes],['Brancos',c.blankVotes],['Nulos (total)',c.nullVotes],['Anulados sub judice',c.subJudiceVotes]].map(([s,v])=>`<div class="stat-row"><span>${s}</span><strong>${n(v)}</strong></div>`).join('')}</div>`;}
function coverage(c){let rs=byCity(),sum=rs.reduce((a,r)=>a+r.votes,0);return rs.length?`<div class="callout"><strong>${n(rs.length)} bairros e localidades · ${n(sum)} votos de Cadorin.</strong> O bairro é o do local de votação. ${sum===c.votes?'A soma confere com o total municipal do candidato.':`Diferença ainda não conciliada: ${n(c.votes-sum)} votos.`}</div>`:`<div class="callout"><strong>Apuração municipal confirmada.</strong> O recorte por bairro está em verificação. Ausência de detalhamento não significa zero voto.</div>`;}
function cityOverview(){const c=currentCity();return `${stats(c)}${amendmentsCitySummary(c)}${coverage(c)}<div class="grid">${panel('Votação por bairro','Bairros com mais votos de Cadorin',byCity().length?bars(byCity()):empty(),'<button class="text-link" data-view="bairros">Ver todos ↗</button>')}${panel('O peso de '+esc(c.name),'Distribuição dos votos de Cadorin em SC',share(c))}</div><div class="grid">${panel('Bairros · resumo','Votos e percentuais no mesmo recorte',neighborhoodTable(true))}${panel('Contexto da eleição','Deputado estadual · '+esc(c.name),summary(c))}</div>${zonesPanel()}${state.city==='81795'?locationMap():''}<p class="small">Arquivo municipal: ${esc(c.generatedDate||'04/10/2026')} às ${esc(c.generatedTime||'21:56:26')} · <a href="${esc(c.source)}" target="_blank" rel="noopener">Ver fonte oficial TSE ↗</a></p>`;}
function tools(citySelect=false){return `<div class="toolbar">${citySelect?`<label class="sr-only" for="city-select">Município</label><select id="city-select" class="select-city">${[...D.municipalities].sort((a,b)=>a.name.localeCompare(b.name,'pt-BR')).map(c=>`<option value="${esc(c.code)}" ${String(c.code)===state.city?'selected':''}>${esc(c.name)}</option>`).join('')}</select>`:''}<label class="sr-only" for="search">Buscar</label><input type="search" id="search" value="${esc(state.search)}" placeholder="Buscar ${state.view==='municipios'?'município':state.view==='locais'?'local ou seção':'bairro'}…"><label class="sr-only" for="sort">Ordenar por</label><select id="sort"><option value="votes" ${state.sort==='votes'?'selected':''}>Mais votos</option><option value="percent" ${state.sort==='percent'?'selected':''}>Maior percentual</option><option value="name" ${state.sort==='name'?'selected':''}>Nome A–Z</option></select></div>`;}
function filtered(rows){const q=state.search.normalize('NFD').replace(/\p{Diacritic}/gu,'').toLowerCase();return rows.filter(r=>(r.name+' '+(r.neighborhood||'')+' '+(r.zone||'')+' '+(r.section||'')+' '+(r.code||'')+' '+(r.sectionNumbers||[]).join(' ')).normalize('NFD').replace(/\p{Diacritic}/gu,'').toLowerCase().includes(q)).sort((a,b)=>state.sort==='name'?a.name.localeCompare(b.name,'pt-BR'):state.sort==='percent'?(pct(b.votes,b.validVotes)||0)-(pct(a.votes,a.validVotes)||0):b.votes-a.votes);}
function paginate(rows,compact=false){let list=compact?rows.slice(0,8):rows.slice(state.page*25,state.page*25+25);return {list,foot:`<div class="table-foot"><span>${compact?Math.min(rows.length,8):Math.min(state.page*25+1,rows.length)}${compact?'':'–'+Math.min((state.page+1)*25,rows.length)} de ${n(rows.length)} registros</span>${compact?'<button class="text-link" data-view="bairros">Abrir detalhamento →</button>':`<div class="pagination"><button data-page="-1" ${state.page===0?'disabled':''} aria-label="Página anterior">←</button><span>${state.page+1} / ${Math.max(1,Math.ceil(rows.length/25))}</span><button data-page="1" ${(state.page+1)*25>=rows.length?'disabled':''} aria-label="Próxima página">→</button></div>`}</div>`};}
function neighborhoodTable(compact=false){let rows=filtered(byCity());if(!rows.length)return byCity().length?noResults():empty();let {list,foot}=paginate(rows,compact);return `<div class="table-wrap"><table><thead><tr><th>Bairro do local</th><th class="num">Votos</th><th class="num">% válidos</th>${compact?'':'<th class="num">% do candidato na cidade</th><th class="num">Válidos no bairro</th><th class="num">Seções</th><th class="num">Locais</th>'}</tr></thead><tbody>${list.map(r=>`<tr><td><button class="row-link" data-neighborhood="${esc(r.name)}">${esc(r.name)}</button></td><td class="num"><strong>${n(r.votes)}</strong></td><td class="num orange">${p(pct(r.votes,r.validVotes))}</td>${compact?'':`<td class="num">${p(pct(r.votes,currentCity().votes))}</td><td class="num">${n(r.validVotes)}</td><td class="num">${n(r.sections)}</td><td class="num">${n(r.locations)}</td>`}</tr>`).join('')}</tbody></table></div>${foot}`;}
function municipalities(){const {list,foot}=paginate(filtered(D.municipalities));return `<div class="metrics">${metric('Votos em Santa Catarina',n(D.state.votes),'Matheus Cadorin · NOVO · 30000',true)}${metric('% dos votos válidos em SC',p(pct(D.state.votes,D.state.validVotes)),n(D.state.validVotes)+' votos válidos no estado')}${metric('Municípios na base',n(D.municipalities.length),'Resultados municipais consultados')}${metric('Votos em Joinville',n(D.municipalities.find(x=>String(x.code)==='81795')?.votes),'Principal recorte desta análise')}</div>${panel('Votação por município','Clique em uma cidade para explorar seus bairros e locais.',tools()+`<div class="table-wrap"><table><thead><tr><th>Município</th><th class="num">Votos</th><th class="num">% válidos locais</th><th class="num">% da votação em SC</th><th class="num">Válidos na cidade</th><th class="num">Seções apuradas</th></tr></thead><tbody>${list.map(r=>`<tr class="${String(r.code)==='81795'?'highlight-row':''}"><td><button class="row-link" data-city="${esc(r.code)}">${esc(r.name)}</button>${String(r.code)==='81795'?'<small>Foco da análise</small>':''}</td><td class="num"><strong>${n(r.votes)}</strong></td><td class="num orange">${p(pct(r.votes,r.validVotes))}</td><td class="num">${p(pct(r.votes,D.state.votes))}</td><td class="num">${n(r.validVotes)}</td><td class="num">${n(r.countedSections)} / ${n(r.totalSections)}</td></tr>`).join('')}</tbody></table></div>${foot}`)}`;}
function neighborhoods(){const c=currentCity();return `${stats(c)}${coverage(c)}${panel('Bairros de '+esc(c.name),'Percentuais calculados sobre votos válidos de deputado estadual em cada bairro.',tools(true)+neighborhoodTable())}`;}
function locationRows(){let rows=byCity(D.locations||[]);if(state.neighborhood)rows=rows.filter(r=>r.neighborhood===state.neighborhood);return filtered(rows);}
function locations(){let c=currentCity(),rows=locationRows(),{list,foot}=paginate(rows);return `${state.neighborhood?neighborhoodStats():''}${state.neighborhood?`<button class="back" data-view="bairros">← Bairros de ${esc(c.name)}</button><div class="callout"><strong>${esc(state.neighborhood)}</strong> · locais de votação neste bairro</div>`:''}${panel('Locais de votação em '+esc(c.name),'Abra um local para consultar suas seções.',tools(true)+(rows.length?`<div class="table-wrap"><table><thead><tr><th>Local de votação</th><th>Bairro</th><th class="num">Zona / local</th><th class="num">Votos</th><th class="num">% válidos</th><th class="num">Seções</th></tr></thead><tbody>${list.map(r=>`<tr><td><button class="row-link" data-location="${esc(r.id)}">${esc(r.name)}</button><small>${esc(r.address||'')}</small></td><td>${esc(r.neighborhood)}</td><td class="num">${esc(r.zone)} / ${esc(r.code)}</td><td class="num"><strong>${n(r.votes)}</strong></td><td class="num orange">${p(pct(r.votes,r.validVotes))}</td><td class="num">${n(r.sections)}</td></tr>`).join('')}</tbody></table></div>${foot}`:(byCity(D.locations||[]).length?noResults():empty())))}`;}
function sections(){const l=D.locations.find(x=>x.id===state.location);if(!l)return locations();const rows=(D.sections||[]).filter(s=>s.locationId===l.id);return `<button class="back" id="back-locations">← Voltar aos locais</button><div class="detail-kicker">${esc(currentCity().name)} / ${esc(l.neighborhood)}</div>${panel(esc(l.name),esc(l.address||'')+` · Zona ${esc(l.zone)} · Local ${esc(l.code)}`,`<div class="panel-body"><div class="large-share"><strong>${n(l.votes)}</strong><span>votos · ${p(pct(l.votes,l.validVotes))} dos válidos neste local</span></div></div><div class="table-wrap"><table><thead><tr><th>Zona</th><th>Seção</th><th class="num">Votos Cadorin</th><th class="num">% válidos</th><th class="num">Votos válidos</th><th class="num">Comparecimento</th><th>Fonte</th></tr></thead><tbody>${rows.map(s=>`<tr><td>${esc(s.zone)}</td><td>${esc(s.section)}${s.aggregatedSections?.length?`<small>Agregadas: ${s.aggregatedSections.map(esc).join(', ')}</small>`:''}</td><td class="num"><strong>${n(s.votes)}</strong></td><td class="num orange">${p(pct(s.votes,s.validVotes))}</td><td class="num">${n(s.validVotes)}</td><td class="num">${n(s.turnout)}</td><td>${s.source?`<a class="text-link" href="${esc(s.source)}" target="_blank" rel="noopener">TSE ↗</a>`:'—'}</td></tr>`).join('')}</tbody></table></div>`)}<p class="small">O código de seção é único dentro de sua zona. Seções agregadas são tratadas conforme a identificação da base oficial. A soma das linhas deve conferir com o total do local.</p>`;}
function methods(){return panel('Fontes e metodologia','Como ler os números e reproduzir os cálculos.',`<div class="panel-body method"><h3>Recorte da análise</h3><p>Eleições gerais de 2026, 1º turno. Matheus Andreis Cadorin, nome de urna Matheus Cadorin, número 30000, NOVO, candidato a deputado estadual por Santa Catarina. O painel começa por Joinville e cobre os 295 municípios de Santa Catarina, incluindo todos os bairros/localidades com locais de votação no cadastro TSE.</p><h3>O significado dos percentuais</h3><ul><li><strong>% dos votos válidos:</strong> votos do candidato ÷ votos válidos para deputado estadual no mesmo município, bairro, local ou seção × 100. Votos válidos incluem os votos nominais válidos e os votos de legenda.</li><li><strong>% da votação em SC:</strong> votos de Cadorin no município ÷ total estadual de Cadorin × 100.</li><li><strong>% do candidato na cidade:</strong> votos de Cadorin no bairro ÷ total municipal de Cadorin × 100.</li></ul><p>Brancos, nulos e anulados sub judice não integram o denominador “votos válidos” deste painel. O percentual exibido diretamente na divulgação do TSE pode usar uma base diferente, incluindo votos sub judice; diferenças de denominador e arredondamento são possíveis. Em Joinville, o TSE usa 332.854 votos concorrentes, incluindo 286 sub judice; este painel usa 332.568 votos válidos. Ambos resultam em 4,52% quando arredondados a duas casas.</p><h3>Bairro do local de votação</h3><p>As seções são relacionadas aos seus locais de votação pela eleição, município, zona e local. O bairro representa o endereço do local de votação e não o domicílio de cada eleitor. Preservamos o bairro/localidade cadastrado pelo TSE. Esse cadastro tem 43 rótulos em Joinville, incluindo localidades rurais, enquanto a prefeitura publica 45 polígonos urbanos. Há diferenças como Distrito Industrial / Zona Industrial Norte, Comasa do Boa Vista / Comasa, e locais de Jardim Sofia e Pirabeiraba dentro do atual Vale Verde. Por isso o mapa mostra pontos dos locais, sem redistribuir os votos entre os nomes de bairro. Registros sem correspondência segura permanecem em “Sem bairro identificado”.</p><h3>Seções agregadas</h3><p>Em Joinville, 1.243 registros cadastrais correspondem a 1.234 seções principais e nove agregadas. Cada boletim principal é contado uma vez. Somamos os votos e os denominadores antes de calcular o percentual de bairros e locais; não usamos médias simples de percentuais.</p><h3>Conferência e cobertura</h3><p id="coverage-method">${esc(D.meta.coverageNote||'Os dados territoriais estão em conciliação. Nenhum resultado ausente é interpretado como zero.')}</p><h3>Locais remanejados</h3><p>${esc(D.meta.territorialNote||'')}</p>${amendmentsMethod()}<h3>Dados e auditorias para download</h3><ul><li><a href="base-completa.json" download>Base consolidada completa (JSON) ↓</a></li><li><a href="auditoria-boletins-sc.json" download>Conferência de todos os 17.326 boletins de SC ↓</a></li><li><a href="auditoria-territorial.json" download>Conferência dos totais por município ↓</a></li><li><a href="auditoria-joinville.json" download>Conferência adicional de Joinville, por zona ↓</a></li></ul><h3>Fontes consultadas</h3><ul>${D.meta.sources.map(s=>`<li><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.name)} ↗</a>${s.note?'<br><span class="small">'+esc(s.note)+'</span>':''}</li>`).join('')}</ul><h3>Atualização</h3><p>${esc(D.meta.snapshotLabel)}. Este painel é um retrato dos arquivos consultados, sujeito a retotalizações da Justiça Eleitoral. Não há atualização automática.</p><h3>Exportação</h3><p>“Exportar dados” baixa os registros da visualização selecionada em CSV, com números sem arredondamento, denominadores e links de origem quando disponíveis.</p></div>`);}
function render(){
  const c=currentCity(),isEmendas=state.view==='emendas',emendaName=D.municipalities.find(x=>String(x.code)===state.emendaCity)?.name;
  $('#main').dataset.view=state.view;
  const labels={joinville:c.name,municipios:'Santa Catarina',bairros:'Bairros de '+c.name,locais:state.location?'Seções eleitorais':'Locais de '+c.name,fontes:'Fontes e metodologia',emendas:emendaName?'Emendas · '+emendaName:'Emendas e votos'};
  $('#title').innerHTML=esc(labels[state.view])+(['joinville','municipios'].includes(state.view)?' <span>SC</span>':'');
  $('#breadcrumb').textContent=labels[state.view];
  $('#subtitle').textContent=isEmendas?'Valores destinados por município e votação de Cadorin em 2026.':state.view==='municipios'?'A distribuição da votação em todo o estado.':'A votação, do município até a seção eleitoral.';
  $('#status').textContent=isEmendas?'Fontes: planilha e TSE':'Fonte: TSE';
  $('#updated').textContent=isEmendas?'Emendas 2023–2025 · planilha recebida em 09/10/2026 · votos consultados em 05/10/2026':D.meta.snapshotLabel;
  $('.snapshot').textContent=isEmendas?'Sem atualização automática':'Retrato da apuração · sem atualização automática';
  $('#content').innerHTML=state.view==='joinville'?cityOverview():state.view==='municipios'?municipalities():state.view==='bairros'?neighborhoods():state.view==='locais'?(state.location?sections():locations()):isEmendas?renderAmendments():methods();
  document.querySelectorAll('nav [data-view]').forEach(b=>{const active=b.dataset.view===state.view&&(state.view!=='joinville'||state.city==='81795');b.classList.toggle('active',active);b.setAttribute('aria-current',active?'page':'false')});
  $('#export').hidden=state.view==='fontes';$('#export').textContent=isEmendas?'↓ Exportar comparação':'↓ Exportar dados';bind();bindAmendments();
}
function bind(){document.querySelectorAll('button[data-view]').forEach(b=>b.onclick=()=>nav(b.dataset.view,b.dataset.view==='joinville'?{city:'81795'}:{}));document.querySelectorAll('[data-city]').forEach(b=>b.onclick=()=>nav('joinville',{city:b.dataset.city}));document.querySelectorAll('[data-neighborhood]').forEach(b=>b.onclick=()=>nav('locais',{neighborhood:b.dataset.neighborhood}));document.querySelectorAll('[data-location]').forEach(b=>{b.onclick=()=>{state.view='locais';state.location=b.dataset.location;state.search='';render()};if(b.tagName.toLowerCase()==='circle')b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();b.onclick()}}});document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{state.page+=Number(b.dataset.page);render()});const search=$('#search');if(search)search.oninput=()=>{const start=search.selectionStart;state.search=search.value;state.page=0;render();$('#search').focus();$('#search').setSelectionRange(start,start)};const sort=$('#sort');if(sort)sort.onchange=()=>{state.sort=sort.value;state.page=0;render()};const select=$('#city-select');if(select)select.onchange=()=>{state.city=select.value;state.search='';state.neighborhood=null;state.location=null;state.page=0;render()};const back=$('#back-locations');if(back)back.onclick=()=>{state.location=null;render()};}
function exportData(){if(state.view==='emendas'){exportAmendments();return;}let rows=state.view==='municipios'?filtered(D.municipalities):state.view==='locais'?(state.location?D.sections.filter(x=>x.locationId===state.location):locationRows()):filtered(byCity());if(!rows.length){$('#export').textContent='Nenhum dado para exportar';return;}rows=rows.map(r=>({...r,municipalityName:D.municipalities.find(c=>String(c.code)===String(r.municipalityCode||r.code))?.name||currentCity().name,year:2026,candidateNumber:30000,percentValid:pct(r.votes,r.validVotes),percentState:pct(r.votes,D.state.votes)}));const labels={code:'codigo',municipalityCode:'codigo_municipio_tse',municipalityName:'municipio',name:'nome',votes:'votos_cadorin',validVotes:'votos_validos_deputado_estadual',officialBase:'votos_concorrentes_tse',officialPct:'percentual_oficial_tse',electorate:'eleitorado',turnout:'comparecimento',nominalVotes:'votos_nominais_validos',nominalValidVotes:'votos_nominais_validos',legendVotes:'votos_legenda',partyVotes:'votos_legenda',technicalNullVotes:'nulos_tecnicos_subconjunto',officialName:'nome_cadastro_tse',officialNeighborhood:'bairro_cadastro_tse',blankVotes:'votos_brancos',nullVotes:'votos_nulos_total',subJudiceVotes:'votos_anulados_sub_judice',totalSections:'secoes_total',countedSections:'secoes_totalizadas',percentValid:'percentual_votos_validos',percentState:'percentual_votos_cadorin_sc',sections:'secoes_principais',locations:'locais_votacao',neighborhood:'bairro_localidade_tse',zone:'zona',section:'secao',aggregatedSections:'secoes_agregadas',sectionNumbers:'numeros_secoes',address:'endereco',source:'fonte',year:'ano',candidateNumber:'numero_candidato'};const keys=[...new Set(rows.flatMap(Object.keys))],cell=v=>{let z=Array.isArray(v)?v.join(', '):String(v??'');if(typeof v==='string'&&/^[=+@-]/.test(z))z="'"+z;return '"'+z.replace(/"/g,'""')+'"';},csv='\uFEFF'+[keys.map(k=>cell(labels[k]||k)).join(';'),...rows.map(r=>keys.map(k=>cell(r[k])).join(';'))].join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='cadorin-2026-'+state.view+'-'+state.city+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
$('#export').onclick=exportData;$('.brand').onclick=e=>{e.preventDefault();nav('joinville',{city:'81795'})};render();

function neighborhoodStats(){const r=byCity().find(x=>x.name===state.neighborhood);if(!r)return '';return `<div class="metrics">${metric('Votos no bairro',n(r.votes),esc(r.name),true)}${metric('% dos válidos no bairro',p(pct(r.votes,r.validVotes)),n(r.validVotes)+' votos válidos')}${metric('Peso na votação da cidade',p(pct(r.votes,currentCity().votes)),'Participação nos votos de Cadorin')}${metric('Locais / seções',n(r.locations)+' / '+n(r.sections),'Seções principais, sem duplicação')}</div>`;}
function locationMap(){const geo=window.JOINVILLE_GEOGRAPHY,locs=byCity(D.locations||[]).filter(x=>Number.isFinite(x.latitude)&&Number.isFinite(x.longitude));if(!geo||!locs.length)return '';const rings=geo.features.flatMap(f=>f.geometry.type==='Polygon'?f.geometry.coordinates:f.geometry.coordinates.flat());const coords=[...rings.flat(),...locs.map(x=>[x.longitude,x.latitude])],xs=coords.map(c=>c[0]*Math.cos(-26.3*Math.PI/180)),ys=coords.map(c=>-c[1]),x0=Math.min(...xs),x1=Math.max(...xs),y0=Math.min(...ys),y1=Math.max(...ys),scale=Math.min(760/(x1-x0),400/(y1-y0)),dx=(800-(x1-x0)*scale)/2,dy=(440-(y1-y0)*scale)/2,project=c=>[(c[0]*Math.cos(-26.3*Math.PI/180)-x0)*scale+dx,(-c[1]-y0)*scale+dy];let max=Math.max(...locs.map(x=>x.votes),1);return panel('Joinville, local por local','Pontos proporcionais aos votos de Cadorin. Clique para abrir as seções.',`<svg class="map-svg" viewBox="0 0 800 440" role="group" aria-label="Mapa dos locais de votação em Joinville">${rings.map(r=>`<path class="boundary" d="${r.map((c,i)=>(i?'L':'M')+project(c).map(v=>v.toFixed(2)).join(',')).join('')}Z"/>`).join('')}${[...locs].sort((a,b)=>b.votes-a.votes).map(l=>{const [x,y]=project([l.longitude,l.latitude]);return `<circle data-location="${esc(l.id)}" cx="${x}" cy="${y}" r="${3+11*Math.sqrt(l.votes/max)}" tabindex="0" role="button" aria-label="${esc(l.name)}, ${n(l.votes)} votos"><title>${esc(l.name)} · ${esc(l.neighborhood)} · ${n(l.votes)} votos · ${p(pct(l.votes,l.validVotes))}</title></circle>`}).join('')}<text x="770" y="25" font-size="14" fill="#566579">N ↑</text></svg><div class="map-caption">Limites urbanos: Prefeitura de Joinville · Locais: TSE · Tamanho do ponto: votos de Cadorin. O bairro das tabelas segue o cadastro eleitoral.</div>`);}
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'consultar_votacao_cadorin_2026',title:'Consultar votação de Cadorin em 2026',description:'Consulta dados oficiais agregados de municípios, bairros ou locais, com bases dos percentuais. Sem alterar a página.',inputSchema:{type:'object',properties:{level:{type:'string',enum:['municipios','bairros','locais']},cityCode:{type:'string'},query:{type:'string'}},required:['level'],additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(!input||!['municipios','bairros','locais'].includes(input.level))throw new Error('Nível inválido.');if(input.cityCode&&!D.municipalities.some(c=>String(c.code)===input.cityCode))throw new Error('Município não encontrado.');const base=input.level==='municipios'?D.municipalities:input.level==='bairros'?D.neighborhoods:D.locations;const rows=base.filter(r=>(!input.cityCode||String(input.level==='municipios'?r.code:r.municipalityCode)===input.cityCode)&&(!input.query||r.name.toLocaleLowerCase('pt-BR').includes(input.query.toLocaleLowerCase('pt-BR'))));return {total:rows.length,rows:rows.slice(0,30).map(r=>({name:r.name,votes:r.votes,validVotes:r.validVotes,percentValid:pct(r.votes,r.validVotes),source:r.source||D.meta.sources[0].url})),snapshot:D.meta.snapshotLabel,method:'Bairro do local de votação no cadastro eleitoral; percentual sobre votos válidos nominais e de legenda.'};}})).catch(()=>{});}catch{}}

function zonesPanel(){let rows=byCity(D.zones||[]);if(!rows.length)return '';return panel('Zonas eleitorais','Recorte do município selecionado, com denominadores próprios.',`<div class="table-wrap"><table><thead><tr><th>Zona</th><th class="num">Votos Cadorin</th><th class="num">% válidos</th><th class="num">Votos válidos</th><th class="num">Comparecimento</th><th class="num">Seções</th></tr></thead><tbody>${rows.sort((a,b)=>b.votes-a.votes).map(r=>`<tr><td><strong>Zona ${esc(r.zone)}</strong></td><td class="num">${n(r.votes)}</td><td class="num orange">${p(pct(r.votes,r.validVotes))}</td><td class="num">${n(r.validVotes)}</td><td class="num">${n(r.turnout)}</td><td class="num">${n(r.sections)}</td></tr>`).join('')}</tbody></table></div>`);}
